//! The time zone borders. data/zones.tsv is generated by src/bin/zones_gen.rs,
//! committed, and embedded in the binary, so loading it cannot fail at
//! runtime: a malformed line means the committed file is broken and panics in
//! dev.

use crate::geo::LonLat;

const DATA: &str = include_str!("../data/zones.tsv");

/// One border, as the file has it.
struct Border<'a> {
    /// The IANA zones on either side, more than two where disputed ground is
    /// claimed by both. The map draws every border alike, so these are only
    /// checked on load.
    #[cfg_attr(not(test), allow(dead_code))]
    zones: Vec<&'a str>,
    points: Vec<LonLat>,
}

/// Every border between zones that keep different clocks, as runs of points
/// to stroke. A run that ends where it starts is a closed loop.
pub fn load() -> Vec<Vec<LonLat>> {
    borders().map(|border| border.points).collect()
}

fn borders() -> impl Iterator<Item = Border<'static>> {
    DATA.lines()
        .enumerate()
        .filter(|(_, line)| !line.is_empty() && !line.starts_with('#'))
        .map(|(i, line)| border(line, i + 1))
}

fn border(line: &str, lineno: usize) -> Border<'_> {
    let (zones, points) = line
        .split_once('\t')
        .unwrap_or_else(|| panic!("data/zones.tsv line {lineno}: no zones"));
    let points: Vec<LonLat> = points
        .split(' ')
        .map(|pair| {
            let (lon, lat) = pair
                .split_once(',')
                .unwrap_or_else(|| panic!("data/zones.tsv line {lineno}: bad pair {pair:?}"));
            LonLat {
                lon: degrees(lon, lineno, pair),
                lat: degrees(lat, lineno, pair),
            }
        })
        .collect();
    assert!(
        points.len() >= 2,
        "data/zones.tsv line {lineno}: a border of {} point",
        points.len()
    );
    Border {
        zones: zones.split(',').collect(),
        points,
    }
}

fn degrees(value: &str, lineno: usize, pair: &str) -> f64 {
    value
        .parse()
        .unwrap_or_else(|_| panic!("data/zones.tsv line {lineno}: bad pair {pair:?}"))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_a_border() {
        let border = border("Asia/Kolkata,Asia/Kathmandu\t80.06,28.84 88.20,26.40", 2);
        assert_eq!(border.zones, ["Asia/Kolkata", "Asia/Kathmandu"]);
        assert_eq!(
            border.points,
            [
                LonLat {
                    lon: 80.06,
                    lat: 28.84
                },
                LonLat {
                    lon: 88.2,
                    lat: 26.4
                }
            ]
        );
    }

    #[test]
    #[should_panic(expected = "line 4: no zones")]
    fn rejects_a_line_without_zones() {
        border("80.06,28.84 88.20,26.40", 4);
    }

    #[test]
    #[should_panic(expected = "line 4: bad pair \"88.20\"")]
    fn rejects_a_point_without_a_latitude() {
        border("Asia/Kolkata,Asia/Kathmandu\t80.06,28.84 88.20", 4);
    }

    #[test]
    #[should_panic(expected = "line 4: a border of 1 point")]
    fn rejects_a_border_of_one_point() {
        border("Asia/Kolkata,Asia/Kathmandu\t80.06,28.84", 4);
    }

    #[test]
    fn loads_the_committed_borders() {
        let borders: Vec<Border> = borders().collect();
        assert!(borders.len() >= 100, "{} borders", borders.len());
        for border in &borders {
            assert!(border.zones.len() >= 2, "{:?} parts nothing", border.zones);
            for zone in &border.zones {
                assert!(
                    jiff::tz::TimeZone::get(zone).is_ok(),
                    "{zone} is not a zone this machine knows"
                );
            }
            for point in &border.points {
                assert!(
                    (-180.0..=180.0).contains(&point.lon) && (-90.0..=90.0).contains(&point.lat),
                    "{point:?} is off the globe"
                );
            }
        }
        // India from Nepal, the quarter-hour one.
        assert!(
            borders.iter().any(|border| {
                border.zones.contains(&"Asia/Kolkata") && border.zones.contains(&"Asia/Kathmandu")
            }),
            "no border between India and Nepal"
        );
    }
}
